#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    /* The program expects an even number of command‑line arguments,
       each pair representing a directed edge u -> v where 0 <= u,v < 8.
       Any violation results in "INVALID_INPUT". */
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 1;
    }

    int adj[8][8] = {{0}};   // adjacency matrix
    int indegree[8] = {0};   // indegree of each vertex
    int done[8] = {0};       // visited flag for topological sort

    /* Parse edges */
    for (int i = 1; i < argc; i += 2) {
        char *endptr;
        long u = strtol(argv[i], &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 1; }
        long v = strtol(argv[i + 1], &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 1; }
        if (u < 0 || u >= 8 || v < 0 || v >= 8) {
            puts("INVALID_INPUT");
            return 1;
        }
        if (!adj[u][v]) {          // avoid double counting the same edge
            adj[u][v] = 1;
            indegree[v]++;
        }
    }

    int order[8];
    int cnt = 0;
    while (cnt < 8) {
        int found = -1;
        for (int v = 0; v < 8; ++v) {
            if (!done[v] && indegree[v] == 0) {
                found = v;
                break;          // pick the smallest index with indegree 0
            }
        }
        if (found == -1) {
            puts("CYCLE");
            return 1;
        }
        done[found] = 1;
        order[cnt++] = found;
        /* Decrease indegree of all vertices reachable from 'found' */
        for (int w = 0; w < 8; ++w) {
            if (adj[found][w]) {
                indegree[w]--;
            }
        }
    }

    for (int i = 0; i < 8; ++i) {
        printf("%d", order[i]);
        putchar(' ');
    }
    putchar('\n');
    return 0;
}
